import numpy as np
# invalid: an emitted bin that is never detected, so its redistribution column sums to zero
redistribution = np.array([
    [0.90, 0.10, 0.0],
    [0.00, 0.80, 0.0],
    [0.00, 0.10, 0.0],
])
resolution = np.eye(3)
args = (redistribution, resolution)
def run_model():
    try:
        compose_detector_response(*args)
        return 0
    except ValueError:
        return 1

import copy as _test_copy

def _independent_inputs(_function):
    def _invoke(*_args, **_kwargs):
        _args, _kwargs = _test_copy.deepcopy((_args, _kwargs))
        return _function(*_args, **_kwargs)
    return _invoke

compose_detector_response = _independent_inputs(compose_detector_response)
assert np.allclose(run_model(), target)

